#pragma once
#include <QHash>
#include <QImage>
#include <QString>
#include <QList>

namespace dzurkel {
struct DocumentSection { QString title; QString anchor; };
// Reader-owned, bounded content. HTML is generated by our readers, never passed
// through from a source document. Images have application-local identifiers.
struct FormattedDocument {
    QString html;
    QString markdown; // Bounded source; parsed with Qt's built-in Markdown parser, HTML disabled.
    QString plainText;
    QString title;
    QString author;
    QString notice;
    QList<DocumentSection> sections;
    QList<DocumentSection> navigation; // Reader-owned unloaded chapter targets.
    QString targetAnchor;
    QHash<QString, QImage> images;
    bool partial = false;
};
}
